/**
 * RAB GUARD — Test Fixtures (Base64 of 3 Test Workbooks)
 * Digunakan untuk pengujian otomatis offline pipeline universal.
 */
(function (window) {
  'use strict';

  window.TEST_WORKBOOKS_B64 = {
    a_standar: '',
    b_order_kolom_beda: '',
    c_irregular: ''
  };

  /**
   * Helper konversi Base64 ke Uint8Array secara offline murni.
   */
  window.b64ToUint8Array = function (b64) {
    var cleanB64 = (b64 || '').replace(/\s+/g, '');
    var bin = atob(cleanB64);
    var len = bin.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) {
      bytes[i] = bin.charCodeAt(i);
    }
    return bytes;
  };
})(typeof window !== 'undefined' ? window : this);